using System.Globalization;
using System.Text;

namespace Bdd.Suite.Testing;

/// <summary>Small pieces of C# source every C# template shares.</summary>
public static class CSharpCode
{
    /// <summary>The first line of every generated file; also how the generator
    /// recognises a file it owns, and may replace or delete.</summary>
    public const string Marker = "// <auto-generated by suiterun generate>";

    /// <summary>The namespace of the run hook and the provider glue.</summary>
    public const string GlueNamespace = "BddSuite.Generated";

    /// <summary>The namespace suite classes go in when the config names none.</summary>
    public const string DefaultNamespace = "BddSuite.Tests";

    /// <summary>A C# string literal of any text.</summary>
    public static string Literal(string text)
    {
        var built = new StringBuilder("\"");
        foreach (var one in text)
        {
            switch (one)
            {
                case '"':
                    built.Append("\\\"");
                    break;
                case '\\':
                    built.Append("\\\\");
                    break;
                case '\n':
                    built.Append("\\n");
                    break;
                case '\r':
                    built.Append("\\r");
                    break;
                case '\t':
                    built.Append("\\t");
                    break;
                default:
                    if (char.IsControl(one) || char.IsSurrogate(one) || one is (char)0x2028 or (char)0x2029)
                    {
                        built.Append(string.Create(CultureInfo.InvariantCulture, $"\\u{(int)one:x4}"));
                    }
                    else
                    {
                        built.Append(one);
                    }
                    break;
            }
        }
        return built.Append('"').ToString();
    }

    /// <summary>A path as generated code holds it: absolute, forward slashes.</summary>
    public static string PathLiteral(string path) => Literal(Path.GetFullPath(path).Replace('\\', '/'));

    /// <summary>The header of a generated file.</summary>
    public static string Header(string provider, string source) =>
        $"{Marker}\n// suiterun generate ({provider}) from {source}.\n// Do not edit: the build writes this file again.\n#nullable enable\n";
}
